// «Mis licencias» en la ficha del cliente: tarjetas compactas con logo, fechas, contador de vigencia y acciones de administración.
async function renderClientLicenses(container,clientId){const box=el('section',undefined,'workspace-section client-licenses');container.append(box);
 async function paint(){box.replaceChildren(el('h2','Mis licencias'),el('p','Cargando…','system-muted'));let data;try{data=await api('/api/clients/'+clientId+'/licenses');}catch(error){box.lastChild.textContent=error.message;return;}
  if(data.can_manage&&!licenseMeta){try{await licenseLoadMeta();}catch{}}
  box.lastChild.remove();const head=box.firstChild;if(data.can_manage){const optout=el('label',undefined,'booking-consent client-licenses-optout'),check=el('input');check.type='checkbox';check.checked=!data.notices_off;optout.append(check,el('span','Recibe avisos de renovación por correo'));check.onchange=async()=>{try{await api('/api/licenses/optout',{client_id:String(clientId),off:!check.checked});toast(check.checked?'El cliente recibirá avisos de renovación.':'El cliente no recibirá avisos de renovación.','success');}catch(error){check.checked=!check.checked;toast(error.message,'error');}};head.after(optout);}
  if(!data.rows.length){box.append(el('p','Este cliente todavía no tiene licencias.','license-hint'));return;}
  const grid=el('div',undefined,'client-license-grid');for(const row of data.rows){const card=el('article',undefined,'client-license'),top=el('header'),title=el('div');title.append(el('strong',row.product),el('small',[row.manufacturer||row.brand,row.kind_label,row.devices?row.devices+' dispositivo'+(row.devices===1?'':'s'):''].filter(Boolean).join(' · ')));
   card.dataset.state=row.state;top.append(catalogLogo({id:row.product_id,image:'1',category:'licencia',name:row.product},{},'catalog-logo license-logo'),title,licenseBadge(row.state,row.state_label));card.append(top);
   const facts=el('dl',undefined,'client-license-facts'),fact=(label,value)=>{const b=el('div');b.append(el('dt',label),el('dd',value||'—'));facts.append(b);};
   fact('Entrega',row.delivered_at?licenseDay(row.delivered_at.slice(0,10)):'');fact('Activación',licenseDay(row.activated_at));fact('Vencimiento',row.expires_at?licenseDay(row.expires_at):(row.state==='pendiente_activacion'?'Al activarse':'Sin vencimiento'));fact('Días restantes',row.days_left===null?'—':String(Math.max(row.days_left,0)));
   fact('Orden',row.order_code);fact('Presupuesto',row.quote_code);card.append(facts,licenseMeter(row));
   if(row.renewal_history.length)card.append(el('p','Renovaciones: '+row.renewal_history.map(r=>licenseDay(r.starts_at)+' → '+licenseDay(r.expires_at)).join(' · '),'license-row-facts'));
   if(data.can_manage)card.append(licenseActionMenu(row,paint));else card.append(el('p','Las acciones y credenciales son de administración.','license-hint'));grid.append(card);}
  box.append(grid);}
 window.clientLicensesReload=paint;await paint();}
